    private static MagicMatch M(MagicMatchKind kind, int start, int end, byte[] pattern, byte[]? mask,
        string? regex, bool needsBacktracking, int minShouldMatch, MagicMatch[] children)
    {
        if (mask is null)
        {
            mask = new byte[pattern.Length];
            System.Array.Fill(mask, (byte)0xFF);
        }
        return new MagicMatch(kind, start, end, pattern, mask, regex, needsBacktracking, minShouldMatch, children);
    }
